package com.example.starter.rolling.domain;

/**
 * 排产单状态：编制 DRAFT → 校验 VALIDATED → 下达 ISSUED → 执行 EXECUTING → 冻结 FROZEN。
 */
public enum ScheduleStatus {
    DRAFT,
    VALIDATED,
    ISSUED,
    EXECUTING,
    FROZEN
}

package com.example.starter.rolling.api.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 排产块请求：一块待轧钢板对应的轧制作业。
 *
 * @param contractNo 轧制合同号
 * @param widthMm    板宽（毫米），须存在于合成宽度档位表
 * @param rollingKm  计划轧制里程（公里）
 * @param warmup     是否烫辊材（换辊后前 5 块排入）
 * @param startTime  作业开始时刻（含）
 * @param endTime    作业结束时刻（不含），与开始时刻构成 [start, end)
 */
public record ScheduleItemRequest(
        @NotBlank String contractNo,
        @NotNull Integer widthMm,
        @NotNull @Positive BigDecimal rollingKm,
        boolean warmup,
        @NotNull LocalDateTime startTime,
        @NotNull LocalDateTime endTime) {
}

package com.example.starter.rolling.api.dto;

import jakarta.validation.constraints.NotNull;

import java.time.LocalDateTime;

/**
 * 换辊窗口请求：半开区间 [startTime, endTime)。
 */
public record RollWindowRequest(
        @NotNull LocalDateTime startTime,
        @NotNull LocalDateTime endTime) {
}

package com.example.starter.rolling.api.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;

import java.util.List;

/**
 * 排产单编制（含修改新版本）请求。
 *
 * @param requestId     幂等键，指纹覆盖该键与全部业务字段
 * @param lineCode      产线编码
 * @param unitCode      轧制单元编码
 * @param baseVersionId 被修改的已下达版本 ID；为空表示首版
 * @param items         轧制作业列表（块序即列表顺序，从 1 开始）
 * @param windows       换辊窗口列表
 */
public record ScheduleCreateRequest(
        @NotBlank String requestId,
        @NotBlank String lineCode,
        @NotBlank String unitCode,
        Long baseVersionId,
        @NotEmpty @Valid List<ScheduleItemRequest> items,
        @Valid List<RollWindowRequest> windows) {
}

package com.example.starter.rolling.api.dto;

import jakarta.validation.constraints.NotNull;

/**
 * 下达请求。
 */
public record IssueRequest(@NotNull String requestId) {
}

package com.example.starter.rolling.api.dto;

import jakarta.validation.constraints.NotNull;

/**
 * 日终冻结请求。
 */
public record FreezeRequest(@NotNull String requestId) {
}

package com.example.starter.rolling.api.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

import java.math.BigDecimal;
import java.time.LocalDateTime;

/**
 * 轧制实绩回传请求，按“合同号＋道次”去重。
 */
public record ActualResultRequest(
        @NotBlank String requestId,
        @NotBlank String lineCode,
        @NotBlank String contractNo,
        @NotNull Integer passNo,
        @NotNull @Positive BigDecimal rollingKm,
        @NotNull LocalDateTime recordedAt) {
}

