        // 不产生新版本；客户端用相同 requestId 重放即可取得首次结果。
        throw new ConflictException(HttpStatus.CONFLICT,
                "requestId " + requestId + " 正在被并发处理，唯一记录已存在，请用相同参数重放");
    }
}

