private static void checkItemOverlaps(List<ScheduleItemRequest> items, List<String> violations) {
    for (int i = 1; i < items.size(); i++) {
        ScheduleItemRequest prev = items.get(i - 1);
        ScheduleItemRequest cur = items.get(i);
        // 半开区间 [start,end)：前块 end > 后块 start 即内部重叠；端点相接合法。
        if (prev.endTime().isAfter(cur.startTime())) {
            violations.add("第" + i + "块（合同 " + prev.contractNo() + "）与第" + (i + 1)
                    + "块（合同 " + cur.contractNo() + "）作业时间内部重叠，半开区间端点相接才合法");
        }
    }
}

